import React from 'react';
import './MainNav.css'; // Import the external CSS

function MainNav() {
  return (
    <nav className="navbar">
      <ul className="navbar-list">
        <li className="navbar-item"><h1>Artists</h1></li>
        <li className="navbar-item"><h1>Events</h1></li>
        <li className="navbar-item"><h1>Marketplace</h1></li>
        <li className="navbar-item"><h1>Donations</h1></li>
        <li className="navbar-item"><h1>Contact Us</h1></li>
        <li className="navbar-item"><h1>Cart</h1></li>
        <li className="navbar-item"><h1>Login</h1></li>
        <li className="navbar-item"><h1>SignUp</h1></li>
        <li className="navbar-item"><h1>Artist Manager Dashboard</h1></li>
      </ul>
    </nav>
  );
}

export default MainNav;
